/**
 * Column helpers shared by every table definition.
 */
import { sql, type SQL } from 'drizzle-orm';
import { customType, text, timestamp, type AnyPgColumn } from 'drizzle-orm/pg-core';
import { newId } from '../ids.js';

/** ULID primary key, generated by the app. */
export const id = () => text('id').primaryKey().$defaultFn(newId);

/** timestamptz read and written as a JS Date. */
export const tstz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

export const createdAt = () => tstz('created_at').notNull().defaultNow();

/** Empty text[] default, written as a literal so the migration is stable. */
export const emptyTextArray = sql`'{}'::text[]`;
export const emptyJsonArray = sql`'[]'::jsonb`;
export const emptyJsonObject = sql`'{}'::jsonb`;

const VOCABULARY_VALUE = /^[a-z0-9_-]+$/;

/**
 * CHECK expression `col in ('a', 'b', ...)` for a closed vocabulary from
 * @hermes-evals/shared. The values are inlined with sql.raw because a CHECK is
 * DDL: drizzle-kit would otherwise write `$1` placeholders into the migration.
 * Only compile-time constants may be passed; each value is validated. `col`
 * may also be an expression, such as a parenthesised `(doc ->> 'state')`.
 */
export function oneOf(col: AnyPgColumn | SQL, values: readonly string[]): SQL {
  for (const value of values) {
    if (!VOCABULARY_VALUE.test(value)) throw new Error(`unsafe vocabulary value: ${value}`);
  }
  return sql`${col} in (${sql.raw(values.map((v) => `'${v}'`).join(', '))})`;
}

/** CHECK expression: a nullable column is either null or in the vocabulary. */
export const nullOrOneOf = (col: AnyPgColumn, values: readonly string[]): SQL =>
  sql`${col} is null or ${oneOf(col, values)}`;

/** CHECK expression: lowercase hex sha256. */
export const isSha256 = (col: AnyPgColumn): SQL => sql`${col} ~ '^[0-9a-f]{64}$'`;

/** CHECK expression: a relative POSIX path with no leading slash and no `..` segment. */
export const isRelativePath = (col: AnyPgColumn): SQL =>
  sql`${col} <> '' and ${col} !~ '(^/|(^|/)\\.\\.(/|$))'`;

/** U+0000 and unpaired UTF-16 surrogates: valid in a JS string, rejected by Postgres text and jsonb. */
// oxlint-disable-next-line no-control-regex -- U+0000 is exactly what must be replaced
const UNSTORABLE = /\u0000|[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g;

/**
 * Replaces the characters Postgres cannot store with U+FFFD. Agent output,
 * tool results and stderr can contain them; dropping a whole event or failing
 * an attempt over one byte would lose evidence. The raw bytes stay in the
 * trial's stderr.log and workspace files.
 */
export const storable = (value: string): string => value.replace(UNSTORABLE, '\uFFFD');

const storableJson = (value: unknown): string =>
  JSON.stringify(value, (_key, item: unknown) => {
    if (typeof item === 'string') return storable(item);
    if (item && typeof item === 'object' && !Array.isArray(item)) {
      return Object.fromEntries(Object.entries(item).map(([k, v]) => [storable(k), v]));
    }
    return item;
  });

/**
 * jsonb column for any JSON value, including a top-level string. Use it for
 * every jsonb column; the DDL is plain jsonb.
 *
 * Drizzle 0.45's built-in jsonb runs JSON.parse a second time on values the
 * driver already parsed, so a stored JSON string "1042" reads back as the
 * number 1042. That would corrupt reference answers. The driver (pg and
 * PGlite) already returns parsed jsonb, so this column returns it untouched.
 * Strings and keys are made storable on the way in.
 *
 * A JS null is written as SQL NULL, because Drizzle skips the encoder for
 * null. To store JSON null, write `toJsonb(value)` or `JSON_NULL`.
 */
export const jsonValue = <T>(name: string) =>
  customType<{ data: T; driverData: unknown }>({
    dataType: () => 'jsonb',
    toDriver: storableJson,
    fromDriver: (value) => value as T,
  })(name);

/** The JSON value null, as opposed to SQL NULL (no value). */
export const JSON_NULL = sql`'null'::jsonb`;

/** Wraps a value for a jsonValue column so that JSON null is stored as JSON null. */
export const toJsonb = <T>(value: T): T | SQL => (value === null ? JSON_NULL : value);

/** text column for content that may quote agent output; made storable on the way in. */
export const storableText = customType<{ data: string; driverData: string }>({
  dataType: () => 'text',
  toDriver: storable,
});
